local F=dofile('tests/fixtures/addon.lua');local test,finish=F.suite()
local function fixture()
    local f=F.new();f.load('Core/custom_authoring.lua');local h=io.open('Core/function_data.lua');if h then h:close();f.load('Core/function_data.lua') end
    f.env.loadstring=function(text,name) local fn,why=loadstring(text,name);if fn then setfenv(fn,f.env) end;return fn,why end
    return f,f.addon
end
local function source(code,bindings) return {name='Original utility',description='Test utility',args={{name='value',type='number'}},returns={{type='number'}},code=code or 'return value',bindings=bindings or {}} end
local function condition(a)
    local source={description='Test condition',icon='Interface\\Icons\\INV_Misc_QuestionMark',fields={}}
    for callback in pairs(a.CustomConditionCallbacks) do source[callback]='' end
    return source
end
local function graph(a)
    assert(a:InstallCustomFunction('BASE',source('return value * 2')))
    assert(a:InstallCustomFunction('MIDDLE',source('return base(value)',{base='BASE'})))
    assert(a:InstallCustomFunction('ROOT',source('return middle(value)',{middle='MIDDLE'})))
end
test('exports bounded transitive closures without evaluating source and carries requirements when excluded',function()
    local _,a=fixture();assert(a.BuildFunctionBundle,'bundle backend missing');graph(a)
    local b=assert(a:BuildFunctionBundle('function','ROOT'));assert(#b.dependencies==2 and #b.requirements==2)
    local bare=assert(a:BuildFunctionBundle('function','ROOT',nil,false));assert(#bare.dependencies==0 and #bare.requirements==2)
    a.db.global.custom_functions.BASE.disabled=true;local disabled=assert(a:BuildFunctionBundle('function','ROOT'));assert(disabled.dependencies[1].source.disabled)
    a.db.global.custom_functions.BASE.bindings={loop='ROOT'};assert(not a:BuildFunctionBundle('function','ROOT'))
end)
test('conflict choices remap data bindings and preserve Lua bytes original names and provenance',function()
    local _,a=fixture();assert(a.BuildFunctionBundle,'bundle backend missing');graph(a);local b=assert(a:BuildFunctionBundle('function','ROOT'))
    local _,destination=fixture();assert(destination:InstallCustomFunction('BASE',source('return value+100')))
    local conflict=assert(destination:PlanFunctionBundleImport(b));assert(not conflict.valid)
    local plan=assert(destination:PlanFunctionBundleImport(b,{BASE={action='rename',id='RENAMED'}}));assert(plan.valid)
    assert(destination:ApplyFunctionBundleImport(plan));assert(destination:ResolveFunctionBinding('ROOT')(3)==6)
    assert(destination.db.global.custom_functions.MIDDLE.bindings.base=='RENAMED' and destination.db.global.custom_functions.MIDDLE.code==b.dependencies[2].source.code)
    assert(destination.db.global.function_import_origins['function:RENAMED'].originalID=='BASE')
end)
test('identical dependencies reuse while builtin identities and duplicate destinations are protected',function()
    local _,a=fixture();assert(a.BuildFunctionBundle,'bundle backend missing');graph(a);local b=assert(a:BuildFunctionBundle('function','ROOT'))
    local plan=assert(a:PlanFunctionBundleImport(b));assert(plan.valid and plan.rows[1].action=='reuse');assert(table.concat(plan.rows[1].effects,',')=='function:MIDDLE,function:ROOT')
    assert(not a:PlanFunctionBundleImport(b,{BASE={action='rename',id='builtin:danger'}}))
    assert(not a:PlanFunctionBundleImport(b,{BASE={action='rename',id='COPY'},MIDDLE={action='rename',id='COPY'}}))
    assert(not a:PlanFunctionBundleImport(b,{UNKNOWN={action='replace'}}))
end)
