test('malformed cyclic oversized duplicate and undeclared-reference bundles fail closed',function()
    local _,a=fixture();assert(a.BuildFunctionBundle,'bundle backend missing');graph(a);local b=assert(a:BuildFunctionBundle('function','ROOT'))
    local cycle=a:CopySettingsData(b);cycle.dependencies[1].source.bindings={loop='ROOT'};assert(not a:PlanFunctionBundleImport(cycle))
    local huge=a:CopySettingsData(b);huge.root.source.code=string.rep('x',65537);assert(not a:PlanFunctionBundleImport(huge))
    local duplicate=a:CopySettingsData(b);duplicate.dependencies[2].id=duplicate.dependencies[1].id;assert(not a:PlanFunctionBundleImport(duplicate))
    local nested={};nested.source=nested;assert(not a:PlanFunctionBundleImport(nested))
    local manual=source('return addon:RequireFunctionBinding("BASE")(value)');assert(not a:BuildFunctionBundle('function','MANUAL',manual))
    local harmless=source('-- addon:RequireFunctionBinding("BASE")\nreturn "addon:RequireFunctionBinding"');assert(a:BuildFunctionBundle('function','HARMLESS',harmless))
    assert(not a:BuildFunctionBundle('function','BRACKET',source('return addon["RequireFunctionBinding"](addon,"BASE")(value)')))
    assert(not a:BuildFunctionBundle('function','ALIAS',source('local api=addon;return api:RequireFunctionBinding("BASE")(value)')))
    assert(not a:BuildFunctionBundle('function','DYNAMIC',source('local api=addon;local key="Require".."FunctionBinding";return api[key](api,"BASE")(value)')))
    assert(not a:BuildFunctionBundle('function','LONG',source('return addon[ [=[RequireFunctionBinding]=] ](addon,"BASE")(value)')))
end)
