    local b=assert(a:BuildFunctionBundle('condition','CUSTOM',c));local tf,target=fixture();tf.load('Core/conditions.lua')
    assert(target:InstallCustomFunction('BASE',source('return value+50')));local oldRegistry=target.functionRegistry;local oldSource=target:CopySettingsData(target.db.global.custom_functions)
    b.root.source.on_register='error("registration failed")';local failed=assert(target:PlanFunctionBundleImport(b,{BASE={action='replace'}}));assert(failed.valid)
    assert(not target:ApplyFunctionBundleImport(failed));assert(target.functionRegistry==oldRegistry and target:SettingsDataEqual(target.db.global.custom_functions,oldSource) and not target.conditionDefinitions.CUSTOM)
    b.root.source.on_register='';local p=assert(target:PlanFunctionBundleImport(b,{BASE={action='rename',id='OTHER_BASE'},ROOT={action='rename',id='OTHER_ROOT'}}));assert(p.valid and target:ApplyFunctionBundleImport(p));assert(target.conditionDefinitions.CUSTOM.evaluate({})==true and target.db.global.custom_conditions.CUSTOM.bindings.helper=='OTHER_ROOT')
