    local b=assert(a:BuildFunctionBundle('function','ROOT'));local _,target=fixture();local p=assert(target:PlanFunctionBundleImport(b));assert(p.valid and #p.warnings>0);assert(target:ApplyFunctionBundleImport(p));assert(target.db.global.custom_functions.BASE.disabled and not target:FunctionAvailable('ROOT'))
