    local _,target=fixture();assert(not assert(target:PlanFunctionBundleImport(b)).valid);assert(target:RegisterBuiltinFunction('builtin:base',builtinSource,function() return function(v) return v end end));local p=assert(target:PlanFunctionBundleImport(b));assert(p.valid and target:ApplyFunctionBundleImport(p))
    local exported=assert(a:BuildFunctionBundle('function','builtin:base'));local preview=assert(target:PlanFunctionBundleImport(exported));assert(not preview.valid);local clone=assert(target:PlanFunctionBundleImport(exported,{['builtin:base']={action='rename',id='CLONE'}}));assert(clone.valid and target:ApplyFunctionBundleImport(clone))
