test('malformed choices counts depth and aggregate source bytes fail without throwing',function()
    local _,a=fixture();graph(a);local b=assert(a:BuildFunctionBundle('function','ROOT'));local ok,value=pcall(a.PlanFunctionBundleImport,a,b,42);assert(ok and not value)
    local count=a:CopySettingsData(b);for i=1,129 do count.dependencies[i]={id='F'..i,source=source()} end;assert(not a:PlanFunctionBundleImport(count))
    local large=source('--'..string.rep('x',60000));local previous
    for i=1,20 do local id='BIG'..i;local copy=a:CopySettingsData(large);if previous then copy.bindings={previous=previous} end;a.db.global.custom_functions[id]=copy;previous=id end
    assert(not a:BuildFunctionBundle('function',previous))
    previous=nil;for i=1,66 do local id='DEEP'..i;a.db.global.custom_functions[id]=source();if previous then a.db.global.custom_functions[id].bindings={previous=previous} end;previous=id end
    assert(not a:BuildFunctionBundle('function',previous))
end)
