    f.env.events={};local old=condition(a);old.bindings={helper='BASE'};old.on_register='table.insert(events,"old-register:"..helper(1))';old.on_unregister='table.insert(events,"old-unregister:"..helper(1))';assert(a:InstallCustomCondition('ROOT',old,nil))
    local _,sender=fixture();assert(sender:InstallCustomFunction('BASE',source('return value+10')));local nextSource=condition(sender);nextSource.bindings={helper='BASE'};nextSource.on_register='table.insert(events,"new-register:"..helper(1));addon.db.global.custom_conditions.ACCIDENT="bad";error("fail")';nextSource.on_unregister='table.insert(events,"new-unregister:"..helper(1))'
    local b=assert(sender:BuildFunctionBundle('condition','ROOT',nextSource));local baseline=a:CopySettingsData(a.db.global.custom_conditions);local definition=a.conditionDefinitions.ROOT;local version=a.conditionRegistryVersion
    local p=assert(a:PlanFunctionBundleImport(b,{BASE={action='replace'},ROOT={action='replace'}}));assert(p.valid);assert(not a:ApplyFunctionBundleImport(p));assert(a.conditionRegistryVersion==version and a.conditionDefinitions.ROOT==definition and a:SettingsDataEqual(a.db.global.custom_conditions,baseline))
