test('bundle rollback restores suspended consumers and releases every resumed registration attempt',function()
    for _,rootKind in ipairs({'function','condition'}) do
        local f,a=fixture();f.load('Core/conditions.lua');local disabled=source('return value+1');disabled.disabled=true;assert(a:InstallCustomFunction('BASE',disabled))
        a.resources={};a.cleanups={};a.failConsumer='CONSUMER'
        for _,id in ipairs({'CONSUMER','OTHER'}) do
            local c=condition(a);c.bindings={helper='BASE'};c.on_register='assert(helper(1)==2);addon.resources[tag]=true;if addon.failConsumer==tag then error("resume failed") end';c.on_unregister='assert(helper(1)==2);addon.resources[tag]=nil;addon.cleanups[tag]=(addon.cleanups[tag] or 0)+1';assert(a:InstallCustomCondition(id,c,nil));assert(a.conditionDefinitions[id].functionSuspended)
        end
        local _,sender=fixture();assert(sender:InstallCustomFunction('BASE',source('return value+1')))
        local root=condition(sender);root.bindings={helper='BASE'};root.on_register='addon.resources[tag]=true';root.on_unregister='assert(helper(1)==2);addon.resources[tag]=nil'
        local bundle=assert(sender:BuildFunctionBundle(rootKind,rootKind=='function' and 'BASE' or 'IMPORTED_CONDITION',rootKind=='condition' and root or nil))
        local beforeSources=a:CopySettingsData(a.db.global.custom_functions);local beforeConditions=a:CopySettingsData(a.db.global.custom_conditions);local oldRegistry,version,conditionVersion=a.functionRegistry,a.functionRegistryVersion,a.conditionRegistryVersion
        local definitions={CONSUMER=a.conditionDefinitions.CONSUMER,OTHER=a.conditionDefinitions.OTHER};local origins=a.db.global.function_import_origins
        local p=assert(a:PlanFunctionBundleImport(bundle,{BASE={action='replace'}}));assert(p.valid);local ok,why=a:ApplyFunctionBundleImport(p)
        assert(not ok and why=='function-consumer-registration-failed','bundle accepted failed consumer resume')
        assert(a.functionRegistry==oldRegistry and a.functionRegistryVersion==version and a.conditionRegistryVersion==conditionVersion)
        assert(a:SettingsDataEqual(a.db.global.custom_functions,beforeSources) and a:SettingsDataEqual(a.db.global.custom_conditions,beforeConditions) and a.db.global.function_import_origins==origins)
        assert(not next(a.resources) and a.cleanups.CONSUMER==1 and a.cleanups.OTHER==1 and not a.conditionDefinitions.IMPORTED_CONDITION)
        for id,definition in pairs(definitions) do assert(a.conditionDefinitions[id]==definition and definition.functionSuspended and definition.functionUnavailable=='disabled-function') end
        a.failConsumer=nil;assert(a:ApplyFunctionBundleImport(p));assert(a:FunctionAvailable('BASE') and a.resources.CONSUMER and a.resources.OTHER)
    end
end)
