test('legacy builtin requirement hashes accept only the exact pre-namespace metadata shape',function()
    local _,sender=fixture();local id='builtin:Platform/spells.lua:Platform_IsSpellReady';local old=source();old.name='Platform_IsSpellReady'
    assert(sender:RegisterBuiltinFunction(id,old,function() return function(value) return value end end))
    local bundle=assert(sender:BuildFunctionBundle('function','ROOT',source('return helper(value)',{helper=id})))
    local _,target=fixture();local current=target:CopySettingsData(old);current.name='IsSpellReady';current.namespace='Platform.spells';local calls=0
    assert(target:RegisterBuiltinFunction(id,current,function() calls=calls+1;return function(value) return value end end))
    assert(target:FunctionSourceHash(current)~=bundle.requirements[1].hash)
    local plan=assert(target:PlanFunctionBundleImport(bundle));assert(plan.valid and calls==0,'metadata-only namespace migration rejected an old dependency or ran its getter')
    assert(target:ApplyFunctionBundleImport(plan) and target:ResolveFunctionBinding('ROOT')(3)==3)
    for _,change in ipairs({function(value) value.code='return value+1' end,function(value) value.args[1].type='string' end,function(value) value.description='Changed documentation' end,function(value) value.bindings={other='MISSING'} end}) do
        target.builtinFunctions[id].source=target:CopySettingsData(current);change(target.builtinFunctions[id].source)
        local review=assert(target:PlanFunctionBundleImport(bundle));assert(not review.valid and review.requirements[1].status=='incompatible-function','legacy compatibility forgave more than namespace/name metadata')
    end
end)
